// Webex signs the raw JSON body with HMAC-SHA1(secret) → X-Spark-Signature.
// Verify against the RAW bytes (never a re-serialised object) with a
// constant-time compare, then hand only the identifiers downstream.
const crypto = require('crypto');
const item = $input.first();
const secret = $env.WEBEX_WEBHOOK_SECRET;
if (!secret) throw new Error('WEBEX_WEBHOOK_SECRET is not set on the n8n container');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const given = String((item.json.headers || {})['x-spark-signature'] || '');
const expected = crypto.createHmac('sha1', secret).update(raw).digest('hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected))) {
  throw new Error('X-Spark-Signature mismatch — request rejected');
}
const body = JSON.parse(raw.toString('utf8'));
if (body.resource !== 'meetingTranscripts' || body.event !== 'created') {
  return []; // not for us; the webhook already answered 200
}
const d = body.data || {};
if (!d.id || !d.meetingId) throw new Error('webhook payload lacks data.id / data.meetingId');
return [{ json: { transcriptId: d.id, meetingId: d.meetingId, webhookName: body.name || '', createdAt: body.created || '' } }];

// Build the preserved-source page and commit it with wiki_apply mode `archive`.
// This step is deterministic and must succeed; compilation is best-effort later.
const meeting = $('Get meeting').first().json;
const transcript = String($input.first().json.transcript || '').trim();
const ids = $('Verify signature').first().json;
if (!transcript) throw new Error('empty transcript for ' + ids.transcriptId);

const kst = (iso) => new Date(new Date(iso).getTime() + 9 * 3600 * 1000);
const pad = (n) => String(n).padStart(2, '0');
const start = kst(meeting.start || ids.createdAt || Date.now());
const date = `${start.getUTCFullYear()}-${pad(start.getUTCMonth() + 1)}-${pad(start.getUTCDate())}`;
const heldAt = `${date}T${pad(start.getUTCHours())}:${pad(start.getUTCMinutes())}:00+09:00`;
const durationMin = meeting.start && meeting.end ? Math.round((new Date(meeting.end) - new Date(meeting.start)) / 60000) : null;
const title = String(meeting.title || meeting.meetingTopic || `Webex 회의 ${date}`).trim();

const t = title.toLowerCase();
const meetingType = /스크럼|scrum|데일리|daily/.test(t) ? 'daily-scrum' : /멘토|mentor/.test(t) ? 'mentoring' : 'planning';
const slugPart = title.replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '').toLowerCase().slice(0, 40) || 'meeting';
const rawPath = `raw/meetings/webex-${date}-${slugPart}`;
const q = (s) => JSON.stringify(String(s));

const fm = [
  '---',
  `title: ${q(title)}`,
  'type: raw',
  'source_type: meetings',
  `date: ${date}`,
  `held_at: ${q(heldAt)}`,
  `meeting_type: ${meetingType}`,
  'source: webex',
  `source_ref: ${q(meeting.webLink || '')}`,
  `host: ${q(meeting.hostDisplayName || '')}`,
  durationMin != null ? `duration_min: ${durationMin}` : null,
  `webex_meeting_id: ${q(ids.meetingId)}`,
  'managed_by: n8n-webex-ingest',
  '---',
].filter(Boolean).join('\n');
const content = `${fm}\n\n# ${title}\n\n> Webex 자동 녹취록 (${heldAt}). 원문은 수정하지 않는다 — 정정은 wiki/ 페이지에서.\n\n${transcript}\n`;

// --- MCP (Streamable HTTP) ---
const mcpUrl = $env.LLM_WIKI_MCP_URL;
const bearer = $env.LLM_WIKI_MCP_BEARER_TOKEN;
if (!mcpUrl || !bearer) throw new Error('LLM_WIKI_MCP_URL / LLM_WIKI_MCP_BEARER_TOKEN not set');
let sessionId = null; let rpcId = 0;
const parse = (res) => {
  const ct = String(res.headers['content-type'] || '');
  const text = typeof res.body === 'string' ? res.body : JSON.stringify(res.body);
  if (ct.includes('text/event-stream')) {
    for (const line of text.split('\n')) if (line.startsWith('data:')) { const d = line.slice(5).trim(); if (d) return JSON.parse(d); }
    throw new Error('SSE without data');
  }
  return text.trim() ? JSON.parse(text) : null;
};
const post = async (payload, expectBody = true) => {
  const headers = { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream', 'Authorization': `Bearer ${bearer}` };
  if (sessionId) headers['Mcp-Session-Id'] = sessionId;
  const res = await this.helpers.httpRequest({ method: 'POST', url: mcpUrl, headers, body: JSON.stringify(payload), returnFullResponse: true, timeout: 120000 });
  const sid = res.headers['mcp-session-id']; if (sid) sessionId = sid;
  if (!expectBody) return null;
  const msg = parse(res);
  if (msg && msg.error) throw new Error(`${payload.method}: ${JSON.stringify(msg.error)}`);
  return msg ? msg.result : null;
};
const call = async (name, args) => {
  const r = await post({ jsonrpc: '2.0', id: ++rpcId, method: 'tools/call', params: { name, arguments: args } });
  const text = (r.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  if (r.isError) throw new Error(`${name} failed: ${text}`);
  try { return JSON.parse(text); } catch { return { text }; }
};
await post({ jsonrpc: '2.0', id: ++rpcId, method: 'initialize', params: { protocolVersion: '2025-03-26', capabilities: {}, clientInfo: { name: 'n8n-webex-ingest', version: '1' } } });
await post({ jsonrpc: '2.0', method: 'notifications/initialized' }, false);

// Webex may deliver the same event more than once, and a rerun after a compile
// failure must not fail here: an already-preserved original is success, not a
// conflict. Preserved sources are create-only, so we never rewrite it either.
let archive; let alreadyArchived = false;
try { await call('wiki_content_read', { uri: rawPath }); alreadyArchived = true; archive = { skipped: 'already archived' }; } catch (e) { /* not there yet */ }
if (!alreadyArchived) {
  archive = await call('wiki_apply', { mode: 'archive', changes: [{ path: rawPath, content }], message: `archive(webex): ${title} ${date}` });
}
return [{ json: { rawPath, title, date, heldAt, meetingType, sourceRef: meeting.webLink || '', alreadyArchived, archive, transcriptChars: transcript.length } }];

// Best-effort compilation. The raw page is already committed; if anything here
// fails the team is told where the raw sits so a person or agent can finish.
const prev = $input.first().json;
const { rawPath, title, date } = prev;
const mcpUrl = $env.LLM_WIKI_MCP_URL; const bearer = $env.LLM_WIKI_MCP_BEARER_TOKEN;
const hermesUrl = $env.HERMES_API_URL; const hermesKey = $env.HERMES_API_KEY;
const slack = $env.WIKI_SLACK_WEBHOOK_URL || '';

let sessionId = null; let rpcId = 0;
const parse = (res) => {
  const ct = String(res.headers['content-type'] || '');
  const text = typeof res.body === 'string' ? res.body : JSON.stringify(res.body);
  if (ct.includes('text/event-stream')) { for (const line of text.split('\n')) if (line.startsWith('data:')) { const d = line.slice(5).trim(); if (d) return JSON.parse(d); } throw new Error('SSE without data'); }
  return text.trim() ? JSON.parse(text) : null;
};
const post = async (payload, expectBody = true) => {
  const headers = { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream', 'Authorization': `Bearer ${bearer}` };
  if (sessionId) headers['Mcp-Session-Id'] = sessionId;
  const res = await this.helpers.httpRequest({ method: 'POST', url: mcpUrl, headers, body: JSON.stringify(payload), returnFullResponse: true, timeout: 120000 });
  const sid = res.headers['mcp-session-id']; if (sid) sessionId = sid;
  if (!expectBody) return null;
  const msg = parse(res); if (msg && msg.error) throw new Error(`${payload.method}: ${JSON.stringify(msg.error)}`); return msg ? msg.result : null;
};
const call = async (name, args) => {
  const r = await post({ jsonrpc: '2.0', id: ++rpcId, method: 'tools/call', params: { name, arguments: args } });
  const text = (r.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  if (r.isError) throw new Error(`${name} failed: ${text}`);
  try { return JSON.parse(text); } catch { return { text }; }
};
const notify = async (msg) => {
  if (!slack) return;
  try { await this.helpers.httpRequest({ method: 'POST', url: slack, body: JSON.stringify({ text: msg }), headers: { 'Content-Type': 'application/json' }, timeout: 10000 }); } catch (e) { /* fail-open */ }
};

try {
  if (!hermesUrl || !hermesKey) throw new Error('HERMES_API_URL / HERMES_API_KEY not set');
  await post({ jsonrpc: '2.0', id: ++rpcId, method: 'initialize', params: { protocolVersion: '2025-03-26', capabilities: {}, clientInfo: { name: 'n8n-webex-ingest', version: '1' } } });
  await post({ jsonrpc: '2.0', method: 'notifications/initialized' }, false);

  const plan = await call('wiki_ingest_plan', { raw_path: rawPath });
  if ((plan.existing_sources || []).length) {
    return [{ json: { ok: true, rawPath, skipped: 'already compiled', existing_sources: plan.existing_sources } }];
  }
  const rules = await call('wiki_rules', {});
  const rawPage = await call('wiki_content_read', { uri: rawPath });
  const rawText = rawPage.content || rawPage.text || JSON.stringify(rawPage);
  const candidates = (plan.candidates || []).slice(0, 6);
  const existing = [];
  for (const c of candidates) {
    try { const p = await call('wiki_content_read', { uri: c.slug }); existing.push({ slug: c.slug, content: p.content || p.text || '' }); } catch (e) { existing.push({ slug: c.slug, error: String(e.message || e) }); }
  }

  const system = `너는 팀 LLM 위키의 ingest 컴파일러다. 아래 규칙(AGENTS.md)을 따른다. 출력은 오직 하나의 \`\`\`json 코드블록이며 그 안은 {"message": string, "changes": [{"path": string, "content": string}]} 형식이다. 설명 문장은 코드블록 밖에 두지 마라.\n\n요구사항:\n- changes 에는 (1) wiki/sources/ 아래 새 source 페이지 1개 — frontmatter 에 raw_source_path: "${rawPath}" 를 반드시 포함, (2) 이 회의에서 무언가를 배운 기존 topics/·people/ 페이지의 **전체 새 내용**(수정본) 1개 이상. 후보 페이지의 현재 내용이 아래에 있으니 그것을 바탕으로 고쳐 써라. 바꿀 것이 없는 페이지는 넣지 마라.\n- raw 페이지(${rawPath})는 이미 커밋돼 있으니 changes 에 넣지 마라.\n- 링크는 [label](topics/t-foo) 또는 [[topics/t-foo]] 형식만. 태그는 소문자-하이픈. 새 페이지 frontmatter 는 title/type/status/summary/last_updated/tags 를 갖춘다 (last_updated: ${date}).\n- 회의 내용을 요약해 source 페이지에 담고, topic 페이지에는 결정·변경·새 사실만 반영하며 source 페이지를 가리켜라.\n- 비밀값·개인정보(이메일·전화)는 쓰지 마라.`;
  const user = `## 위키 규칙 (wiki_rules)\n${typeof rules === 'string' ? rules : (rules.text || rules.rules || JSON.stringify(rules))}\n\n## ingest 계획 (wiki_ingest_plan)\n${JSON.stringify({ required: plan.required, candidates, existing_sources: plan.existing_sources, notes: plan.notes }, null, 1)}\n\n## 후보 페이지 현재 내용\n${existing.map(e => `### ${e.slug}\n${e.content || ('(읽기 실패: ' + e.error + ')')}`).join('\n\n')}\n\n## 원문 (${rawPath})\n${rawText}`;

  const res = await this.helpers.httpRequest({
    method: 'POST', url: `${hermesUrl.replace(/\/$/, '')}/v1/chat/completions`,
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${hermesKey}`, 'X-Hermes-Session-Key': `webex-ingest-${date}-${Math.random().toString(36).slice(2, 8)}` },
    body: JSON.stringify({ model: $env.HERMES_MODEL || 'gpt-5.5', messages: [{ role: 'system', content: system }, { role: 'user', content: user }], stream: false }),
    json: false, timeout: 900000,
  });
  const data = typeof res === 'string' ? JSON.parse(res) : res;
  const text = String(((data.choices || [])[0] || {}).message?.content || '');
  const m = text.match(/```json\s*([\s\S]*?)```/);
  if (!m) throw new Error('Hermes 응답에 json 코드블록이 없음: ' + text.slice(0, 300));
  const draft = JSON.parse(m[1]);
  const changes = (draft.changes || []).filter(c => c && c.path && typeof c.content === 'string' && !c.path.startsWith('raw/'));
  if (!changes.some(c => c.path.startsWith('sources/'))) throw new Error('초안에 sources/ 페이지가 없음');
  // A model that returns a truncated topic page would have wiki_apply commit the
  // deletion faithfully. A rewrite that loses more than 40% of an existing page is
  // not an update we accept unattended — refuse and let a person look.
  for (const ch of changes) {
    const before = existing.find(e => e.slug === ch.path && e.content);
    if (before && ch.content.length < before.content.length * 0.6) {
      throw new Error(`초안이 기존 페이지 ${ch.path} 를 ${before.content.length}→${ch.content.length}자로 줄임 — 자동 반영 거부`);
    }
  }

  const applied = await call('wiki_apply', { mode: 'knowledge', changes, message: draft.message || `ingest(knowledge): ${title} — webex ${date}`, expected_head: plan.head });
  return [{ json: { ok: true, rawPath, compiled: changes.map(c => c.path), apply: applied } }];
} catch (e) {
  const reason = String(e.message || e).slice(0, 600);
  await notify(`⚠️ Webex 회의 자동 ingest — 컴파일 실패. 원문은 보관됨: \`${rawPath}\`\n사유: ${reason}\n→ 에이전트에게 "${rawPath} 를 ingest 해줘" 라고 요청하면 마무리됩니다.`);
  return [{ json: { ok: false, rawPath, error: reason } }];
}
